mapper.insert:
insert into spas_study_group(
    dept_id, subject_id, group_name, leader_student_id, status, sort_order,
    create_by, create_time, remark
) values (
    #{deptId}, #{subjectId}, #{groupName}, #{leaderStudentId},
    coalesce(#{status}, '0'), coalesce(#{sortOrder}, 0),
    #{createBy}, now(), #{remark}
)

mapper.update:
update spas_study_group
group_name = #{groupName}, leader_student_id = #{leaderStudentId}, leader_student_id = null, subject_id = #{subjectId}, status = #{status}, sort_order = #{sortOrder}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where group_id = #{groupId}

update spas_study_group set status = '1', update_time = now()
where group_id in
#{id}

update spas_study_group_member
set role_in_group = #{roleInGroup}
where group_id = #{groupId} and student_id = #{studentId} and leave_time is null

mapper.select:
select s.student_id as studentId, s.student_no as studentNo, s.student_name as studentName,
       s.dept_id as deptId, s.status
from spas_student s
where s.del_flag = '0' and s.status = '0' and s.dept_id = #{deptId}
  and not exists (
    select 1 from spas_study_group_member m
    inner join spas_study_group g on g.group_id = m.group_id and g.status = '0'
    where m.student_id = s.student_id and m.leave_time is null
      and g.dept_id = #{deptId}

        and g.subject_id = #{subjectId}
        and g.subject_id is null

  )
order by s.student_no


where g.status = '0' and g.dept_id = #{deptId}

    and g.subject_id = #{subjectId}
    and g.subject_id is null

  and exists (
    select 1 from spas_study_group_member m
    where m.group_id = g.group_id and m.student_id = #{studentId} and m.leave_time is null
  )
limit 1

select count(1)
from spas_study_group_member m
inner join spas_study_group g on g.group_id = m.group_id and g.status = '0'
where m.student_id = #{studentId} and m.leave_time is null
  and g.dept_id = #{deptId}

    and g.subject_id = #{subjectId}
    and g.subject_id is null

  and g.group_id <> #{excludeGroupId}
